class Solution {
  public int numRabbits(int[] answers) {
    java.util.Map<Integer, Integer> remaining = new java.util.HashMap<>();
    int result = 0;
    for (int answer : answers) {
      int count = remaining.getOrDefault(answer, 0);
      if (count == 0) {
        result += answer + 1;
        remaining.put(answer, answer);
      } else remaining.put(answer, count - 1);
    }
    return result;
  }
}
